  for (const m of String(text ?? '').matchAll(NUM_RE)) {
    const raw = m[2];
    const pct = !!(m[1] || m[3]);
    if (!raw.includes(',') && !pct) continue;
    const decimals = raw.includes(',') ? raw.split(',')[1].length : 0;
    const v = Math.abs(Number(raw.replace(/\./g, '').replace(',', '.')));
    const tol = 0.5 * 10 ** -decimals + 1e-9;
    if (!knownNumbers.some((k) => Math.abs(v - k) <= Math.max(tol, k * 0.001))) errors.push(`${owner}: '${m[0].trim()}' verilerde bulunamadı`);
  }
};
if (llm) {
  checkText('summary', llm.summary);
  findings.forEach((f) => checkText(f.id, f.statement));
}

// 5) Veri kalitesi
const stale = ctx.data_quality?.stale_inputs ?? [];
const failed = ctx.data_quality?.failed_sources ?? [];
const snapN = payload.market_snapshot.length;
const dqStatus = snapN === 0 || stale.length > snapN / 2 ? 'poor' : stale.length || failed.length ? 'degraded' : 'ok';
const notes = [];
if (stale.length) notes.push(`Bayat seriler: ${stale.join(', ')}`);
if (failed.length) notes.push(`Çalışmayan kaynaklar: ${failed.join(', ')}`);

const asOf = ctx.as_of;
const fmt = (x) => Number(x).toFixed(2).replace('.', ',');
let title = String(llm?.title ?? '').slice(0, 200);
let summary = String(llm?.summary ?? '').slice(0, 3000);
let priority = pick(llm?.priority, ['low', 'normal', 'high', 'critical'], 'normal');
let outFindings = findings;
let fallback = false;

if (errors.length && ATTEMPT >= 2) {
  // Şablon rapor: sayılar doğrudan paketten, yorum yok
  fallback = true;
  const top = payload.market_snapshot
    .filter((s) => s.change_1d_pct !== null && !s.is_stale && s.segment !== 'fx')
    .sort((a, b) => Math.abs(b.zscore_1d ?? 0) - Math.abs(a.zscore_1d ?? 0))
    .slice(0, 5)
    .map((s) => `${s.name} ${fmt(s.value)} ${s.unit} (%${fmt(s.change_1d_pct)})`);
  const moves = payload.market_moves.filter((m) => m.zscore !== null).map((m) => `${m.instrument_code} (z ${fmt(m.zscore)}, ${m.status === 'explained' ? 'haberle açıklanıyor' : 'haberle açıklanamadı'})`);
  summary = [
    'Otomatik veri özeti (yorum üretilemedi).',
    top.length ? `Öne çıkan fiyatlar: ${top.join('; ')}.` : 'Güncel fiyat verisi yok.',
    moves.length ? `Olağan dışı hareketler: ${moves.join('; ')}.` : '',
    payload.news.length ? `${payload.news.length} haber kümesi ayrıntıda.` : '',
  ].filter(Boolean).join(' ');
  title = '';
  outFindings = [];
  payload.risks = [];
  priority = payload.market_moves.length ? 'high' : 'normal';
  notes.push(`LLM yorumu doğrulamadan geçmedi: ${errors.slice(0, 5).join('; ')}`);
}

const typeName = meta.report_type === 'morning_brief' ? 'Sabah bülteni' : 'Gün sonu raporu';
const report = {
  schema_version: '1.0',
  report_id: pack.report_id,
  supersedes: null,
  agent: { id: 'energy-news', version: '0.1.0', run_id: String($execution.id) },
  report_type: meta.report_type,
  generated_at: new Date().toISOString(),
  as_of: asOf,
  period: { start: new Date(Date.parse(asOf) - meta.lookback_hours * 3600000).toISOString(), end: new Date(Date.parse(asOf)).toISOString() },
  priority,
  language: 'tr',
  title: title || `${typeName} ${String(asOf).slice(0, 10)}`,
  summary,
  findings: outFindings,
  evidence,
  data_quality: { status: dqStatus, stale_inputs: stale, failed_sources: failed, notes: notes.join(' | ') },
  payload,
};
return [{ json: { valid: fallback || errors.length === 0, fallback, errors, report, dedup_key: meta.dedup_key, llm_content: content } }];
